151	        /// <inheritdoc/>
152	        public Task<ItemUpdateType> RefreshSingleItem(BaseItem item, MetadataRefreshOptions options, CancellationToken cancellationToken)
153	        {
154	            var type = item.GetType();
155	
156	            var service = _metadataServices.FirstOrDefault(current => current.CanRefreshPrimary(type))
157	                ?? _metadataServices.FirstOrDefault(current => current.CanRefresh(item));
158	
159	            if (service is null)
160	            {
161	                _logger.LogError("Unable to find a metadata service for item of type {TypeName}", type.Name);
162	                return Task.FromResult(ItemUpdateType.None);
163	            }
164	
165	            return service.RefreshMetadata(item, options, cancellationToken);
166	        }
