382	        private IEnumerable<IImageProvider> GetImageProvidersInternal(BaseItem item, LibraryOptions libraryOptions, MetadataOptions options, ImageRefreshOptions refreshOptions, bool includeDisabled)
383	        {
384	            var typeOptions = libraryOptions.GetTypeOptions(item.GetType().Name);
385	            var fetcherOrder = typeOptions?.ImageFetcherOrder ?? options.ImageFetcherOrder;
386	
387	            return _imageProviders.Where(i => CanRefreshImages(i, item, typeOptions, refreshOptions, includeDisabled))
388	                .OrderBy(i => GetConfiguredOrder(fetcherOrder, i.Name))
389	                .ThenBy(GetDefaultOrder);
390	        }
