392	        private bool CanRefreshImages(
393	            IImageProvider provider,
394	            BaseItem item,
395	            TypeOptions? libraryTypeOptions,
396	            ImageRefreshOptions refreshOptions,
397	            bool includeDisabled)
398	        {
399	            try
400	            {
401	                if (!provider.Supports(item))
402	                {
403	                    return false;
404	                }
405	            }
406	            catch (Exception ex)
407	            {
408	                _logger.LogError(ex, "{ProviderName} failed in Supports for type {ItemType} at {ItemPath}", provider.GetType().Name, item.GetType().Name, item.Path);
409	                return false;
410	            }
411	
412	            if (includeDisabled || provider is ILocalImageProvider)
413	            {
414	                return true;
415	            }
416	
417	            if (item.IsLocked && refreshOptions.ImageRefreshMode != MetadataRefreshMode.FullRefresh)
418	            {
419	                return false;
420	            }
421	
422	            return _baseItemManager.IsImageFetcherEnabled(item, libraryTypeOptions, provider.Name);
423	        }
