440	        private IEnumerable<IMetadataProvider<T>> GetMetadataProvidersInternal<T>(BaseItem item, LibraryOptions libraryOptions, MetadataOptions globalMetadataOptions, bool includeDisabled, bool forceEnableInternetMetadata)
441	            where T : BaseItem
442	        {
443	            var localMetadataReaderOrder = libraryOptions.LocalMetadataReaderOrder ?? globalMetadataOptions.LocalMetadataReaderOrder;
444	            var typeOptions = libraryOptions.GetTypeOptions(item.GetType().Name);
445	            var metadataFetcherOrder = typeOptions?.MetadataFetcherOrder ?? globalMetadataOptions.MetadataFetcherOrder;
446	
447	            return _metadataProviders.OfType<IMetadataProvider<T>>()
448	                .Where(i => CanRefreshMetadata(i, item, typeOptions, includeDisabled, forceEnableInternetMetadata))
449	                .OrderBy(i =>
450	                    // local and remote providers will be interleaved in the final order
451	                    // only relative order within a type matters: consumers of the list filter to one or the other
452	                    i switch
453	                    {
454	                        ILocalMetadataProvider => GetConfiguredOrder(localMetadataReaderOrder, i.Name),
455	                        IRemoteMetadataProvider => GetConfiguredOrder(metadataFetcherOrder, i.Name),
456	                        // Default to end
457	                        _ => int.MaxValue
458	                    })
459	                .ThenBy(GetDefaultOrder);
460	        }
461	
462	        private bool CanRefreshMetadata(
463	            IMetadataProvider provider,
464	            BaseItem item,
465	            TypeOptions? libraryTypeOptions,
466	            bool includeDisabled,
467	            bool forceEnableInternetMetadata)
468	        {
469	            if (!item.SupportsLocalMetadata && provider is ILocalMetadataProvider)
470	            {
471	                return false;
472	            }
473	
474	            if (includeDisabled)
475	            {
476	                return true;
477	            }
478	
479	            // If locked only allow local providers
480	            if (item.IsLocked && provider is not ILocalMetadataProvider && provider is not IForcedProvider)
481	            {
482	                return false;
483	            }
484	
485	            if (forceEnableInternetMetadata || provider is not IRemoteMetadataProvider)
486	            {
487	                return true;
488	            }
489	
490	            return _baseItemManager.IsMetadataFetcherEnabled(item, libraryTypeOptions, provider.Name);
491	        }
