493	        private static int GetConfiguredOrder(string[] order, string providerName)
494	        {
495	            var index = Array.IndexOf(order, providerName);
496	
497	            if (index != -1)
498	            {
499	                return index;
500	            }
501	
502	            // default to end
503	            return int.MaxValue;
504	        }
505	
506	        private static int GetDefaultOrder(object provider)
507	        {
508	            if (provider is IHasOrder hasOrder)
509	            {
510	                return hasOrder.Order;
511	            }
512	
513	            // after items that want to be first (~0) but before items that want to be last (~100)
514	            return 50;
515	        }
