538	        private MetadataPluginSummary GetPluginSummary<T>()
539	            where T : BaseItem, new()
540	        {
541	            // Give it a dummy path just so that it looks like a file system item
542	            var dummy = new T
543	            {
544	                Path = Path.Combine(_appPaths.InternalMetadataPath, "dummy"),
545	                ParentId = Guid.NewGuid()
546	            };
547	
548	            var options = GetMetadataOptions(dummy);
549	
550	            var summary = new MetadataPluginSummary
551	            {
552	                ItemType = typeof(T).Name
553	            };
554	
555	            var libraryOptions = new LibraryOptions();
556	
557	            var imageProviders = GetImageProvidersInternal(
558	                dummy,
559	                libraryOptions,
560	                options,
561	                new ImageRefreshOptions(new DirectoryService(_fileSystem)),
562	                true).ToList();
563	
564	            var pluginList = summary.Plugins.ToList();
565	
566	            AddMetadataPlugins(pluginList, dummy, libraryOptions, options);
567	            AddImagePlugins(pluginList, imageProviders);
568	
569	            // Subtitle fetchers
570	            var subtitleProviders = _subtitleManager.GetSupportedProviders(dummy);
571	            pluginList.AddRange(subtitleProviders.Select(i => new MetadataPlugin
572	            {
573	                Name = i.Name,
574	                Type = MetadataPluginType.SubtitleFetcher
575	            }));
576	
577	            // Lyric fetchers
578	            var lyricProviders = _lyricManager.GetSupportedProviders(dummy);
579	            pluginList.AddRange(lyricProviders.Select(i => new MetadataPlugin
580	            {
581	                Name = i.Name,
582	                Type = MetadataPluginType.LyricFetcher
583	            }));
584	
585	            // Media segment providers
586	            var mediaSegmentProviders = _mediaSegmentManager.GetSupportedProviders(dummy);
587	            pluginList.AddRange(mediaSegmentProviders.Select(i => new MetadataPlugin
588	            {
589	                Name = i.Name,
590	                Type = MetadataPluginType.MediaSegmentProvider
591	            }));
592	
593	            summary.Plugins = pluginList.ToArray();
594	
595	            var supportedImageTypes = imageProviders.OfType<IRemoteImageProvider>()
596	                .SelectMany(i => i.GetSupportedImages(dummy))
597	                .ToList();
598	
599	            supportedImageTypes.AddRange(imageProviders.OfType<IDynamicImageProvider>()
600	                .SelectMany(i => i.GetSupportedImages(dummy)));
601	
602	            summary.SupportedImageTypes = supportedImageTypes.Distinct().ToArray();
603	
604	            return summary;
605	        }
