607	        private void AddMetadataPlugins<T>(List<MetadataPlugin> list, T item, LibraryOptions libraryOptions, MetadataOptions options)
608	            where T : BaseItem
609	        {
610	            var providers = GetMetadataProvidersInternal<T>(item, libraryOptions, options, true, true).ToList();
611	
612	            // Locals
613	            list.AddRange(providers.Where(i => i is ILocalMetadataProvider).Select(i => new MetadataPlugin
614	            {
615	                Name = i.Name,
616	                Type = MetadataPluginType.LocalMetadataProvider
617	            }));
618	
619	            // Fetchers
620	            list.AddRange(providers.Where(i => i is IRemoteMetadataProvider).Select(i => new MetadataPlugin
621	            {
622	                Name = i.Name,
623	                Type = MetadataPluginType.MetadataFetcher
624	            }));
625	
626	            // Savers
627	            list.AddRange(_savers.Where(i => IsSaverEnabledForItem(i, item, libraryOptions, ItemUpdateType.MetadataEdit, true)).OrderBy(i => i.Name).Select(i => new MetadataPlugin
628	            {
629	                Name = i.Name,
630	                Type = MetadataPluginType.MetadataSaver
631	            }));
632	        }
