634	        private void AddImagePlugins(List<MetadataPlugin> list, List<IImageProvider> imageProviders)
635	        {
636	            // Locals
637	            list.AddRange(imageProviders.Where(i => i is ILocalImageProvider).Select(i => new MetadataPlugin
638	            {
639	                Name = i.Name,
