726	        /// <summary>
727	        /// Determines whether [is saver enabled for item] [the specified saver].
728	        /// </summary>
729	        private bool IsSaverEnabledForItem(IMetadataSaver saver, BaseItem item, LibraryOptions libraryOptions, ItemUpdateType updateType, bool includeDisabled)
730	        {
731	            var options = GetMetadataOptions(item);
732	
733	            try
734	            {
735	                if (!saver.IsEnabledFor(item, updateType))
736	                {
737	                    return false;
738	                }
739	
740	                if (!includeDisabled)
741	                {
742	                    if (libraryOptions.MetadataSavers is null)
743	                    {
744	                        if (options.DisabledMetadataSavers.Contains(saver.Name, StringComparison.OrdinalIgnoreCase))
745	                        {
746	                            return false;
747	                        }
748	
749	                        if (!item.IsSaveLocalMetadataEnabled())
750	                        {
751	                            if (updateType >= ItemUpdateType.MetadataEdit)
752	                            {
753	                                // Manual edit occurred
754	                                // Even if save local is off, save locally anyway if the metadata file already exists
755	                                if (saver is not IMetadataFileSaver fileSaver || !File.Exists(fileSaver.GetSavePath(item)))
756	                                {
757	                                    return false;
758	                                }
759	                            }
760	                            else
761	                            {
762	                                // Manual edit did not occur
763	                                // Since local metadata saving is disabled, consider it disabled
764	                                return false;
765	                            }
766	                        }
767	                    }
768	                    else
769	                    {
770	                        if (!libraryOptions.MetadataSavers.Contains(saver.Name, StringComparison.OrdinalIgnoreCase))
771	                        {
772	                            return false;
773	                        }
774	                    }
775	                }
776	
777	                return true;
778	            }
779	            catch (Exception ex)
780	            {
781	                _logger.LogError(ex, "Error in {Saver}.IsEnabledFor", saver.Name);
782	                return false;
783	            }
784	        }
