933	        /// <inheritdoc/>
934	        public void OnRefreshStart(BaseItem item)
935	        {
936	            _logger.LogDebug("OnRefreshStart {Item:N}", item.Id);
937	            _activeRefreshes[item.Id] = 0;
938	            try
939	            {
940	                RefreshStarted?.Invoke(this, new GenericEventArgs<BaseItem>(item));
941	            }
942	            catch (Exception ex)
943	            {
