977	        /// <inheritdoc/>
978	        public void OnRefreshProgress(BaseItem item, double progress)
979	        {
980	            var id = item.Id;
981	            _logger.LogDebug("OnRefreshProgress {Id:N} {Progress}", id, progress);
982	
983	            if (!_activeRefreshes.TryGetValue(id, out var current)
984	                || progress <= current
985	                || !_activeRefreshes.TryUpdate(id, progress, current))
986	            {
987	                // Item isn't currently refreshing, or update was received out-of-order, so don't trigger event.
988	                return;
989	            }
990	
991	            try
992	            {
993	                RefreshProgress?.Invoke(this, new GenericEventArgs<Tuple<BaseItem, double>>(new Tuple<BaseItem, double>(item, progress)));
994	            }
995	            catch (Exception ex)
996	            {
997	                // EventHandlers should never propagate exceptions, but we have little control over plugins...
998	                _logger.LogError(ex, "Invoking {RefreshEvent} event handlers failed", nameof(RefreshProgress));
999	            }
