1147	        /// <summary>
1148	        /// Releases unmanaged and optionally managed resources.
1149	        /// </summary>
1150	        /// <param name="disposing"><c>true</c> to release both managed and unmanaged resources; <c>false</c> to release only unmanaged resources.</param>
1151	        protected virtual void Dispose(bool disposing)
1152	        {
1153	            if (_disposed)
1154	            {
1155	                return;
1156	            }
1157	
1158	            if (disposing)
1159	            {
1160	                if (!_disposeCancellationTokenSource.IsCancellationRequested)
1161	                {
1162	                    _disposeCancellationTokenSource.Cancel();
1163	                }
1164	
1165	                _disposeCancellationTokenSource.Dispose();
1166	                _imageSaveLock.Dispose();
1167	            }
1168	
1169	            _disposed = true;
1170	        }
